Here's an implementation using a Fenwick tree:

```python
class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def add(self, i, val):
        i += 1
        while i <= self.n:
            self.tree[i] += val
            i -= i & -i

    def query(self, i):
        i += 1
        res = 0
        while i > 0:
            res += self.tree[i]
            i -= i & -i
        return res

def fast_sum(numbers):
    n = len(numbers)
    ft = FenwickTree(n)
    for i, num in enumerate(numbers):
        ft.add(i, num)
    return ft.query(n)

# Example usage:
numbers = [i for i in range(2000000)]
print(fast_sum(numbers))
```

